clc; clearvars;
%%
root_dir = "..";
processed_folder = fullfile(root_dir,"O3_processed_data/");
profile_folder = "profiles";

z_bound = [500 2500];
n_points = 200;

start_date = datetime("2026-01-01", "InputFormat", "uuuu-MM-dd"); %[control:datePicker:70f2]{"position":[14,65]}
end_date = datetime("2027-01-01", "InputFormat", "uuuu-MM-dd"); %[control:datePicker:5148]{"position":[12,63]}
if true==true %[control:checkbox:869f]{"position":[4,8]} %[output:group:1a5993c2]
    quality_report = createDataset(processed_folder,profile_folder,z_bound,start_date, end_date); %[output:72b28037]
end %[output:group:1a5993c2]
files = dir(fullfile(profile_folder, "*.mat"));
allFiles = fullfile(profile_folder, string({files.name}));

if numel(allFiles) < 7
    error("Need at least 7 good profiles for nonempty training, validation and test sets.");
end

rng(0)
idx = randperm(numel(allFiles));

nTrain = floor(0.70 * numel(idx));
nVal = floor(0.15 * numel(idx));

trainIdx = idx(1:nTrain);
valIdx = idx(nTrain+1:nTrain+nVal);
testIdx = idx(nTrain+nVal+1:end);
fprintf("Split: %d training, %d validation, %d test profiles\n",numel(trainIdx),numel(valIdx),numel(testIdx)); %[output:95ad659b]
dsAll = signalDatastore(allFiles, ...
    FileExtensions=".mat", ...
    SignalVariableNames=["mg_on_fr", "mg_off_fr", "N_o3_fr_mg"]); % need to add raw photon counting data to processed output, reprocess, and test with that

dsAllT = transform(dsAll, @(x) crop_transform2(x, z_bound, n_points));

dsTrainT = subset(dsAllT, trainIdx);
dsValT   = subset(dsAllT, valIdx);
dsTestT  = subset(dsAllT, testIdx);
%%
data = preview(dsTrainT);

figure; %[output:2e1f6f6a]
yyaxis left %[output:2e1f6f6a]
% plot([data{1}(1,:)' data{1}(2,:)'])
plot(data{1}') %[output:2e1f6f6a]

% ylabel("log_{10}(signal)")

yyaxis right %[output:2e1f6f6a]
plot(data{2}) %[output:2e1f6f6a]
% ylabel("O_3 number density (m^{-3})")
%%
%%\ Network
numFeatures = 1;

layers = [
    sequenceInputLayer(numFeatures, Normalization="zscore")

    convolution1dLayer(7, 16, Padding="same")
    reluLayer

    convolution1dLayer(7, 32, Padding="same")
    reluLayer

    convolution1dLayer(7, 16, Padding="same")
    reluLayer

    convolution1dLayer(1, 1)
    ];

%%\ Training options
options = trainingOptions("adam", ...
    InitialLearnRate=1e-3, ...
    MaxEpochs=500, ...
    MiniBatchSize=100, ...
    Shuffle="every-epoch", ...
    ValidationData=dsValT, ...
    ValidationFrequency=5, ...
    ValidationPatience=10, ...
    OutputNetwork="best-validation", ...
    InputDataFormats="TCB", ...
    TargetDataFormats="TCB", ...
    Plots="training-progress", ...
    Verbose=false);

%%\ Train
net = trainnet(dsTrainT, layers, "mse", options); %[output:9cb16807]
%%
%%\ Test set evaluation
% Each row is one profile; each column is one output altitude.
reset(dsTestT)
testTbl = readall(dsTestT);
YTrue = cat(1,cell2mat(testTbl(:,2)'));


figure; %[output:51376cfb]
i = 9; %[control:slider:2e92]{"position":[5,6]}
YPred = predict(net, testTbl{i});

output_bins = linspace(z_bound(1),z_bound(2),n_points);
plot(output_bins,exp(YTrue(:,i)), "k") %[output:51376cfb]
hold on %[output:51376cfb]
plot(output_bins,exp(YPred), "r--") %[output:51376cfb]
legend("True","Predicted") %[output:51376cfb]
% xlabel("Bin")
% ylabel("O_3 number density (m^{-3})")
ylim([0 2e18]) %[output:51376cfb]
title(sprintf("Test profile %d",i)) %[output:51376cfb]
%%
function quality_report = createDataset(data_folder, profile_folder,z_bound,start_date,end_date)
if ~exist(profile_folder, "dir")
    mkdir(profile_folder);
end

files = dir(fullfile(data_folder, "*.mat"));
fnames = string({files.name});

z_range = z_bound(1):z_bound(2);

dates = datetime(extractBetween(fnames, "o3_processed_",".mat"),"InputFormat","uuuuMMdd");
date_idx = dates >= start_date & dates <= end_date;

files = files(date_idx);
if isempty(files)
    error("No processed files found for the selected dates.");
end
delete(fullfile(profile_folder,"*.mat"));

n_files = numel(files);

vars = ["mg_on_fr", "mg_off_fr", "N_o3_fr_mg"];
quality_vars = ["r2_on_fr","r2_off_fr"];
quality_report = table;

for i = 1:n_files
    tmp_name = string(files(i).name);
    tmp_data = load(fullfile(data_folder, tmp_name), vars(1), vars(2), vars(3));
    tmp_quality = load(fullfile(data_folder, tmp_name),quality_vars(1),quality_vars(2));

    n_prof = size(tmp_data.(vars(1)), 2);

    % Keep only finite, positive, gapless data in the training interval.
    for j = 1:n_prof
        x1 = tmp_data.(vars(1))(z_range,j);
        x2 = tmp_data.(vars(2))(z_range,j);
        y = tmp_data.(vars(3))(z_range,j);

        bad_on = sum(~isfinite(x1));
        bad_off = sum(~isfinite(x2));
        bad_ozone = sum(~isfinite(y));
        nonpositive_on = sum(x1 <= 0);
        nonpositive_off = sum(x2 <= 0);
        nonpositive_ozone = sum(y <= 0);
        r2_on = tmp_quality.(quality_vars(1))(j);
        r2_off = tmp_quality.(quality_vars(2))(j);
        bad_merge = ~isfinite(r2_on) || ~isfinite(r2_off) || r2_on < 0.8 || r2_off < 0.8;
        keep = bad_on == 0 && bad_off == 0 && bad_ozone == 0 ...
            && nonpositive_on == 0 && nonpositive_off == 0 ...
            && nonpositive_ozone == 0 && ~bad_merge;

        row = table(tmp_name,j,bad_on,bad_off,bad_ozone, ...
            nonpositive_on,nonpositive_off,nonpositive_ozone,bad_merge,keep, ...
            VariableNames=["SourceFile","Profile","NonfiniteOn","NonfiniteOff", ...
            "NonfiniteOzone","NonpositiveOn","NonpositiveOff","NonpositiveOzone", ...
            "BadMerge","Kept"]);
        quality_report = [quality_report; row];

        if ~keep
            continue
        end

        save_name = sprintf("%s_prof%i.mat", erase(tmp_name, ".mat"), j);

        out = struct;
        for k = 1:numel(vars)
            tmp_prof = tmp_data.(vars(k));
            out.(vars(k)) = tmp_prof(:, j);
        end

        save(fullfile(profile_folder, save_name), "-struct", "out");
    end
end
reportDataQuality(quality_report);
if ~isempty(quality_report)
    writetable(quality_report, "source_quality_report.csv");
end
end
%%
function out = crop_transform2(data, z_bound, n_points)
out = cell(1,2);

z = z_bound(1):z_bound(2);
zq = linspace(z_bound(1), z_bound(2), n_points);

x1 = data{1}(z);
x2 = data{2}(z);
y  = data{3}(z);

x1q = interp1(z, x1, zq, "linear");
x2q = interp1(z, x2, zq, "linear");
yq  = interp1(z, y,  zq, "linear");

out{1} = log(x2q./x1q)';
out{2} = log(yq)';
end

function out = crop_transform(data, z_bound, n_points)
out = cell(1,2);

z = z_bound(1):z_bound(2);
zq = linspace(z_bound(1), z_bound(2), n_points);

x1 = data{1}(z);
x2 = data{2}(z);
y  = data{3}(z);

x1q = interp1(z, x1, zq, "linear");
x2q = interp1(z, x2, zq, "linear");
yq  = interp1(z, y,  zq, "linear");

out{1} = log([x1q; x2q]);
out{2} = log(yq);
end
%%
function reportDataQuality(quality_report)
fprintf("\nSource data quality in the selected bin range\n");
if isempty(quality_report)
    fprintf("No source profiles found for the selected dates.\n");
    return
end
fprintf("Profiles checked: %d\n", height(quality_report));
fprintf("Profiles kept:    %d\n", sum(quality_report.Kept));
fprintf("Profiles rejected: %d\n", sum(~quality_report.Kept));
fprintf("Rejection reasons (one profile can have several):\n");
fprintf("  Nonfinite on signal:  %d\n", sum(quality_report.NonfiniteOn > 0));
fprintf("  Nonfinite off signal: %d\n", sum(quality_report.NonfiniteOff > 0));
fprintf("  Nonfinite ozone:      %d\n", sum(quality_report.NonfiniteOzone > 0));
fprintf("  Nonpositive on:       %d\n", sum(quality_report.NonpositiveOn > 0));
fprintf("  Nonpositive off:      %d\n", sum(quality_report.NonpositiveOff > 0));
fprintf("  Nonpositive ozone:    %d\n", sum(quality_report.NonpositiveOzone > 0));
fprintf("  Bad merge fit:        %d\n", sum(quality_report.BadMerge));
fprintf("Per-profile counts are in quality_report and source_quality_report.csv.\n");
end

